-- chair-step: inverse of read_lane_v2_b3_04_agent_message_template_detail — un-enrolls agent.message_template_detail from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'message_template_detail' and is_active);
select iam.apply_rls('agent', 'message_template_detail', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'message_template_detail' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'message_template_detail' and is_active));
